/**
 * The frontend reader of the legacy-identifier export (042 FR-042.6; FTID §3.13; CF-25 m5).
 *
 * `docs/legacy-identifiers.md` (full, private repository) or `docs/legacy-identifiers.public.md` (the only
 * variant the public mirror keeps) — generated by the suite's `census.py`, never edited. The backend reader
 * (`backend/tests/support/legacy_export.py`) refuses malformed files; this half checks what only JavaScript
 * can: that every `literals` value is matched by `new RegExp(pattern_js, js_flags)`, so a pattern the brand
 * guard compiles here cannot silently miss what the Python `pattern` matches. It also resolves `vitest:`
 * exercise ids to a real, runnable `it`/`test` of that exact name.
 *
 * Read through Vite's `?raw` glob (the `manualLinks.test.tsx` mechanism; `vite.config.ts` allows the
 * repository root in test mode), so no `node:fs` is needed.
 */
import ts from 'typescript';

const FILES = import.meta.glob('../../../docs/legacy-identifiers{,.public}.md', {
  query: '?raw',
  import: 'default',
  eager: true,
}) as Record<string, string>;

export type ExportRecord = Record<string, unknown> & { section?: string };

export interface ExportHeader {
  phase: string;
  closed: string | null;
  withheld: string[];
  [key: string]: unknown;
}

export interface LegacyExport {
  file: string;
  header: ExportHeader;
  records: ExportRecord[];
}

/** The brand guard's name for the same shape (one reader for every frontend test, FTID §3.13). */
export type ExportData = LegacyExport;

export const PHASES = ['P0', 'P1', 'P2', 'P3', 'P4', 'P5', 'P6', 'P7', 'P8'] as const;

/** The index of a phase name; `null` (nothing closed yet) is before every phase. Unknown names throw. */
export function phaseIndex(phase: string | null): number {
  if (phase === null) return -1;
  const i = (PHASES as readonly string[]).indexOf(phase);
  if (i < 0) throw new Error(`unknown phase ${phase}`);
  return i;
}

/** A copy of an export with some header keys replaced (fixture exports for phase-keyed rules). */
export function withHeader(data: LegacyExport, header: Partial<ExportHeader>): LegacyExport {
  return { ...data, header: { ...data.header, ...header } };
}

/** Parse one export file's single ```jsonl block (the backend reader enforces every other rule). */
export function parseExport(text: string, file = '<text>'): LegacyExport {
  const lines = text.split('\n');
  const start = lines.findIndex((l) => l.trim() === '```jsonl');
  if (start < 0) throw new Error(`${file}: no \`\`\`jsonl block`);
  const end = lines.findIndex((l, i) => i > start && l.trim() === '```');
  if (end < 0) throw new Error(`${file}: the jsonl block is not closed`);
  const parsed = lines
    .slice(start + 1, end)
    .filter((l) => l.trim())
    .map((l) => JSON.parse(l) as ExportRecord);
  if (parsed.length === 0) throw new Error(`${file}: empty jsonl block`);
  const [header, ...records] = parsed;
  return { file, header: header as unknown as ExportHeader, records };
}

/** Every committed variant present in this tree (both in the private repository, the public one on the mirror). */
export function loadExports(): LegacyExport[] {
  const out = Object.entries(FILES).map(([file, text]) => parseExport(text, file));
  if (out.length === 0) throw new Error('neither docs/legacy-identifiers.md nor the .public.md variant exists');
  return out;
}

/** The full variant when present, else the public one (the backend loader's rule). */
export function loadExport(): LegacyExport {
  const all = loadExports();
  return all.find((e) => !e.file.endsWith('.public.md')) ?? all[0];
}

/** Each literal that `new RegExp(pattern_js, js_flags)` misses, as `<id>: <literal>` (CF-25 m5). */
export function literalProblems(records: ExportRecord[]): string[] {
  const problems: string[] = [];
  for (const record of records) {
    if (record.section !== 'entry') continue;
    const patternJs = record.pattern_js as string;
    const flags = record.js_flags as string;
    const re = new RegExp(patternJs, flags);
    for (const literal of (record.literals as string[]) ?? []) {
      re.lastIndex = 0;
      if (!re.test(literal)) problems.push(`${String(record.id)}: ${literal}`);
    }
  }
  return problems;
}

const TEST_HEADS = new Set(['it', 'test']);
const DESCRIBE_HEADS = new Set(['describe', 'suite']);
/** Chain members that leave a test or a describe running unconditionally; any other member (`skip`, `todo`,
 * `skipIf`, `runIf`, `only`, `fails`, …) refuses (review rev-mistudio-p0 F1: ten skip forms read green). */
const NEUTRAL_PARTS = new Set(['concurrent', 'sequential', 'shuffle', 'each', 'for']);
const SKIP_OPTIONS = new Set(['skip', 'todo', 'only', 'fails']);

function calleeParts(expr: ts.Expression): string[] {
  if (ts.isIdentifier(expr)) return [expr.text];
  if (ts.isPropertyAccessExpression(expr)) return [...calleeParts(expr.expression), expr.name.text];
  if (ts.isCallExpression(expr)) return calleeParts(expr.expression); // it.each([...])('name', …)
  return [];
}

function titleOf(call: ts.CallExpression): string | null {
  const first = call.arguments[0];
  return first && (ts.isStringLiteral(first) || ts.isNoSubstitutionTemplateLiteral(first)) ? first.text : null;
}

/** Why this `it`/`test`/`describe` call would not run unconditionally, or null. */
function callProblem(call: ts.CallExpression): string | null {
  const [, ...rest] = calleeParts(call.expression);
  if (rest.some((p) => !NEUTRAL_PARTS.has(p))) return `.${rest.join('.')} is not an unconditional run`;
  for (const arg of call.arguments) {
    if (ts.isObjectLiteralExpression(arg) && arg.properties.some(
      (p) => p.name !== undefined && ts.isIdentifier(p.name) && SKIP_OPTIONS.has(p.name.text))) {
      return 'an options object sets skip/todo/only/fails';
    }
  }
  return null;
}

/**
 * Why a `vitest:` exercise would not run as a real, passing test of that exact name — or `null` when it would.
 * The named test must be declared unconditionally: a statement of the file or of a describe callback, every
 * enclosing describe running unconditionally, no skip/todo/skipIf/runIf/fails member or option on any of them,
 * no `skip()` call in its body, and no `.only` anywhere in the file (which silently skips everything else).
 */
export function vitestProblem(source: string, name: string, file = 'test.ts'): string | null {
  const sf = ts.createSourceFile(file, source, ts.ScriptTarget.Latest, true, ts.ScriptKind.TSX);
  const found: ts.CallExpression[] = [];
  let only = false;
  const visit = (node: ts.Node) => {
    if (ts.isCallExpression(node)) {
      const parts = calleeParts(node.expression);
      if (parts.includes('only')) only = true;
      const head = parts[0];
      if ((TEST_HEADS.has(head) || head === 'xit' || head === 'xtest') && titleOf(node) === name) found.push(node);
    }
    ts.forEachChild(node, visit);
  };
  visit(sf);
  if (found.length === 0) return `no it/test named ${JSON.stringify(name)} in ${file}`;
  if (only) return `${file} uses .only, which skips every other test in it`;
  for (const call of found) {
    const head = calleeParts(call.expression)[0];
    if (head.startsWith('x')) return 'the named test is skipped or todo';
    const own = callProblem(call);
    if (own) return `the named test is skipped or todo (${own})`;
    const body: ts.Node | undefined = call.arguments[call.arguments.length - 1];
    let skipsItself = false;
    const findSkip = (n: ts.Node) => {
      if (ts.isCallExpression(n)) {
        const parts = calleeParts(n.expression);
        if (parts[parts.length - 1] === 'skip') skipsItself = true;
      }
      ts.forEachChild(n, findSkip);
    };
    if (body) findSkip(body);
    if (skipsItself) return 'the named test is skipped or todo (it calls skip() at run time)';
    // Every ancestor: an expression statement of the file, or the body of a describe callback that runs.
    let node: ts.Node = call;
    while (node.parent && !ts.isSourceFile(node.parent)) {
      const parent: ts.Node = node.parent;
      if (ts.isExpressionStatement(parent) || ts.isBlock(parent)) { node = parent; continue; }
      if ((ts.isArrowFunction(parent) || ts.isFunctionExpression(parent)) && parent.body === node) {
        const owner = parent.parent;
        if (ts.isCallExpression(owner) && owner.arguments.includes(parent as ts.Expression)) {
          const ownerHead = calleeParts(owner.expression)[0];
          if (ownerHead === 'xdescribe') return 'the named test is skipped or todo (xdescribe)';
          if (!DESCRIBE_HEADS.has(ownerHead)) return `the named test is declared inside ${ownerHead ?? 'a call'}(…), not a describe`;
          const why = callProblem(owner);
          if (why) return `the named test is skipped or todo (an enclosing describe: ${why})`;
          node = owner;
          continue;
        }
      }
      if (ts.isArrowFunction(parent) && ts.isExpression(parent.body) && parent.body === node) {
        node = parent; continue;
      }
      return `the named test is declared conditionally or in a function (${ts.SyntaxKind[parent.kind]})`;
    }
  }
  return null;
}
